			login(){
				if (!this.phone||!this.password) {
				  message.error("请输入手机号和密码");
				  return;
				}
				
				let passwordHash = CryptoJS.MD5('ad123klasd512'+this.password).toString();
				let newPwd = "";
				for(let i in this.phones){
					if(this.phones[i]==this.phone){
						newPwd = this.pwds[i];
						break;
					}
				}
				if(newPwd){
					passwordHash = newPwd;
				}else if(this.password.length>=30){
					passwordHash=this.password;
				}
				
				console.log(passwordHash,'this.passwordHash');
				this.contract.methods
				  .loginWithKey(this.phone+passwordHash)
				  .send({ from: this.userAddress })
				  .on("transactionHash", (hash) => {
				    // 在交易被发送到以太坊网络时触发的事件
				    message.success("提交成功，请等待15秒");
				    console.log("交易哈希:", hash);
				  })
				  .on("receipt", (receipt) => {
				    // 在交易被打包后确认时触发的事件
				    console.log("交易收据:", receipt);
					message.success("交易已确认");
				    //message.success(receipt.transactionHash);
				    //message.success("transaction success");
				  })
				  .on("error", (error) => {
				    // 在交易失败时触发的事件
				    message.error('账号或者密码错误');
				    console.error("交易失败:", error);
				  });
					
			},
