			async loadData(toPageFlag) {
				if (this.contract) {
					try {
						// 调用合约方法
						if (!this.loaded) {
							Spin.show('Loading');
						}
						try{
							if(this.state==1){
								console.log(this.userAddress,'this.userAddress');
								let userInfo = await this.contract.methods.getUserInfo(this.userAddress).call({ from: this.userAddress });
								console.log(userInfo,'userInfo');
								if(userInfo&&userInfo[0]!='0'){
									this.state=2;
									userInfo[0] = parseFloat(this.web3.utils.fromWei(userInfo[0], "ether"));
									userInfo[1] = parseFloat(this.web3.utils.fromWei(userInfo[1], "ether"));
									userInfo[3] = parseFloat(this.web3.utils.fromWei(userInfo[3], "ether"));
									userInfo[4] = parseFloat(this.web3.utils.fromWei(userInfo[4], "ether"));
									if(userInfo[2]=='86400'){
